def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split off pre-release (everything after '-')
        if '-' in v_without_build:
            parts = v_without_build.split('-', 1)
            version_part = parts[0]
            prerelease = parts[1]
        else:
            version_part = v_without_build
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(int(x) for x in version_part.split('.'))

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
            parsed_prerelease = []
            for pid in prerelease_ids:
                if pid.isdigit():
                    parsed_prerelease.append((0, int(pid)))
                else:
                    parsed_prerelease.append((1, pid))
            prerelease_tuple = tuple(parsed_prerelease)
        else:
            prerelease_tuple = None

        return (version_nums, prerelease_tuple)

    def compare_key(v):
        version_nums, prerelease_tuple = parse_version(v)

        # For sorting: version with prerelease should come before version without
        # So if prerelease_tuple is None, use a tuple that sorts after any prerelease
        if prerelease_tuple is None:
            prerelease_key = (1,)  # Sorts after (0, ...)
        else:
            prerelease_key = (0, prerelease_tuple)

        return (version_nums, prerelease_key)

    # Use stable sort to preserve input order for equal precedence
    return sorted(versions, key=compare_key)

